32, \\u043a\\u043e\\u0442\\u043e\\u0440\\u044b\\u0435 \\u043d\\u0430\\u0434\\u043e \\u044f\\u0432\\u043d\\u043e \\u0437\\u0430\\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c \\u043a\\u0430\\u043a \\u0442\\u0440\\u0435\\u0431\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435, \\u0430 \\u043d\\u0435 \\u043a\\u0430\\u043a \\u0434\\u0430\\u043d\\u043d\\u043e\\u0435.\\n\\n## 2) \\u041f\\u043b\\u0430\\u043d approach'\\u0430 \\u043a \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441\\u0443 \\u00abOPRO-\\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u044f vs CoT-\\u0431\\u0430\\u0437\\u0430 vs empty \\u043d\\u0430 BBH\\u00bb\\n\\n**\\u0415\\u0434\\u0438\\u043d\\u0438\\u0446\\u0430 \\u0441\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u044f.** \\u0422\\u0440\\u0451\\u0445\\u0443\\u0440\\u043e\\u0432\\u043d\\u0435\\u0432\\u043e: (a) \\u044d\\u043b\\u0435\\u043c\\u0435\\u043d\\u0442 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0438 (item, 1 \\u043f\\u0440\\u043e\\u043c\\u043f\\u0442 = 1 \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441 BBH) \\u2014 \\u0434\\u043b\\u044f \\u043f\\u0430\\u0440\\u043d\\u044b\\u0445 \\u0442\\u0435\\u0441\\u0442\\u043e\\u0432; (b) **BBH-\\u043f\\u043e\\u0434\\u0437\\u0430\\u0434\\u0430\\u0447\\u0430 (task)** \\u2014 \\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u0430\\u044f \\u0435\\u0434\\u0438\\u043d\\u0438\\u0446\\u0430 \\u0434\\u043b\\u044f \\u043e\\u0431\\u043e\\u0431\\u0449\\u0435\\u043d\\u0438\\u044f \\u0438 \\u0441\\u0442\\u0430\\u0442\\u0438\\u0441\\u0442\\u0438\\u043a\\u0438 (\\u0438\\u043c\\u0435\\u043d\\u043d\\u043e tasks, \\u0430 \\u043d\\u0435 items, \\u043e\\u0433\\u0440\\u0430\\u043d\\u0438\\u0447\\u0438\\u0432\\u0430\\u044e\\u0442 \\u043c\\u043e\\u0449\\u043d\\u043e\\u0441\\u0442\\u044c); (c) \\u043c\\u0430\\u043a\\u0440\\u043e-\\u0441\\u0440\\u0435\\u0434\\u043d\\u0435\\u0435 \\u043f\\u043e held-out tasks \\u2014 \\u043f\\u0435\\u0440\\u0432\\u0438\\u0447\\u043d\\u044b\\u0439 \\u044d\\u043d\\u0434\\u043f\\u043e\\u0438\\u043d\\u0442. \\u0412\\u0441\\u0435 \\u0443\\u0441\\u043b\\u043e\\u0432\\u0438\\u044f \\u0441\\u0440\\u0430\\u0432\\u043d\\u0438\\u0432\\u0430\\u044e\\u0442\\u0441\\u044f \\u043d\\u0430 **\\u043e\\u0434\\u043d\\u0438\\u0445 \\u0438 \\u0442\\u0435\\u0445 \\u0436\\u0435 item'\\u0430\\u0445** (\\u043f\\u0430\\u0440\\u043d\\u044b\\u0439 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d), \\u0440\\u0430\\u0441\\u0445\\u043e\\u0436\\u0434\\u0435\\u043d\\u0438\\u0435 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0432 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0435 \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0438.\\n\\n**\\u0423\\u0441\\u043b\\u043e\\u0432\\u0438\\u044f (within-subject, \\u0432\\u0441\\u0451 \\u043e\\u0441\\u0442\\u0430\\u043b\\u044c\\u043d\\u043e\\u0435 \\u0438\\u0434\\u0435\\u043d\\u0442\\u0438\\u0447\\u043d\\u043e):**\\n- A \\u2014 OPRO-\\u043e\\u043f\\u0442\\u0438\\u043c\\u0438\\u0437\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u0430\\u044f \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u044f (\\u0435\\u0434\\u0438\\u043d\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u0430\\u044f \\u00abgeneral\\u00bb \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u044f, \\u043e\\u043f\\u0442\\u0438\\u043c\\u0438\\u0437\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u0430\\u044f \\u043d\\u0430 train-\\u043f\\u043e\\u0434\\u043c\\u043d\\u043e\\u0436\\u0435\\u0441\\u0442\\u0432\\u0435 BBH-tasks, \\u043a\\u0430\\u043a \\u0432 \\u043e\\u0440\\u0438\\u0433\\u0438\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u043c \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b\\u0435).\\n- B \\u2014 zero-shot CoT-\\u0431\\u0430\\u0437\\u0430: \\u0440\\u043e\\u0432\\u043d\\u043e `Let's think step by step.` (Kojima et al.).\\n- C \\u2014 empty prompt (\\u0432\\u043e\\u043f\\u0440\\u043e\\u0441 + \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0439 answer-format \\u0445\\u0432\\u043e\\u0441\\u0442).\\n- A\\u2032 (\\u0430\\u0431\\u043b\\u044f\\u0446\\u0438\\u044f, \\u0432\\u0442\\u043e\\u0440\\u0438\\u0447\\u043d\\u043e) \\u2014 \\u0442\\u0430 \\u0436\\u0435 OPRO-\\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u044f, \\u043d\\u043e \\u0441 \\u0432\\u044b\\u0440\\u0435\\u0437\\u0430\\u043d\\u043d\\u044b\\u043c\\u0438 \\u0432\\u0441\\u0442\\u0440\\u043e\\u0435\\u043d\\u043d\\u044b\\u043c\\u0438 few-shot \\u043f\\u0440\\u0438\\u043c\\u0435\\u0440\\u0430\\u043c\\u0438: \\u0440\\u0430\\u0437\\u0434\\u0435\\u043b\\u044f\\u0435\\u0442 \\u00ab\\u0443\\u043c\\u043d\\u044b\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442 \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0438\\u00bb \\u043e\\u0442 \\u00ab\\u0441\\u043f\\u0440\\u044f\\u0442\\u0430\\u043d\\u043d\\u044b\\u0445 few-shot \\u043f\\u0440\\u0438\\u043c\\u0435\\u0440\\u043e\\u0432\\u00bb (\\u0433\\u043b\\u0430\\u0432\\u043d\\u044b\\u0439 \\u043a\\u043e\\u043d\\u0444\\u0430\\u0443\\u043d\\u0434 OPRO).\\n- D (\\u043e\\u043f\\u0446\\u0438\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e, reference) \\u2014 human few-shot CoT \\u0438\\u0437 BBH/CoT-\\u0431\\u0443\\u043c\\u0430\\u0433\\u0438 \\u043a\\u0430\\u043a \\u043f\\u043e\\u0442\\u043e\\u043b\\u043e\\u043a-\\u043e\\u0440\\u0438\\u0435\\u043d\\u0442\\u0438\\u0440; \\u0438 \\u0447\\u0435\\u043a\\u043f\\u043e\\u0438\\u043d\\u0442\\u044b OPRO-\\u0438\\u0442\\u0435\\u0440\\u0430\\u0446\\u0438\\u0439 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0438\\u0432\\u043e\\u0439 \\u043e\\u0431\\u0443\\u0447\\u0435\\u043d\\u0438\\u044f, \\u0435\\u0441\\u043b\\u0438 \\u043f\\u043e\\u044f\\u0432\\u044f\\u0442\\u0441\\u044f \\u043b\\u043e\\u0433\\u0438.\\n\\u0424\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u044e\\u0442\\u0441\\u044f \\u0438 \\u0443\\u0440\\u0430\\u0432\\u043d\\u0438\\u0432\\u0430\\u044e\\u0442\\u0441\\u044f: answer-format suffix, max_tokens, stop-\\u0441\\u0435\\u043a\\u0432\\u0435\\u043d\\u0446\\u0438\\u0438, \\u0442\\u0440\\u0438\\u043c\\u043c\\u0438\\u043d\\u0433, \\u043f\\u0430\\u0440\\u0441\\u0435\\u0440 \\u043e\\u0442\\u0432\\u0435\\u0442\\u0430, \\u0432\\u0435\\u0440\\u0441\\u0438\\u044f \\u043f\\u0440\\u043e\\u043c\\u043f\\u0442-\\u0448\\u0430\\u0431\\u043b\\u043e\\u043d\\u0430.\\n\\n**\\u0412\\u044b\\u0431\\u043e\\u0440 \\u043f\\u043e\\u0434\\u0437\\u0430\\u0434\\u0430\\u0447 BBH.** 27 \\u0437\\u0430\\u0434\\u0430\\u0447. Primary-\\u043a\\u043e\\u043d\\u0442\\u0440\\u0430\\u0441\\u0442 **\\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043f\\u043e held-out (test) \\u0437\\u0430\\u0434\\u0430\\u0447\\u0430\\u043c** \\u0438\\u0437 \\u043e\\u0431\\u0443\\u0447\\u0430\\u044e\\u0449\\u0435\\u0433\\u043e \\u0440\\u0430\\u0437\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u044f OPRO (train-\\u0437\\u0430\\u0434\\u0430\\u0447\\u0438 \\u0441\\u043e\\u043e\\u0431\\u0449\\u0435\\u043d\\u0438\\u0439 \\u043d\\u0435 \\u0432 \\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u043e\\u0439 \\u044d\\u043d\\u0434\\u043f\\u043e\\u0438\\u043d\\u0442, \\u0430 \\u0432 \\u00abtrain\\u2013test gap\\u00bb). \\u041f\\u043b\\u044e\\u0441 \\u0441\\u0442\\u0440\\u0430\\u0442\\u0438\\u0444\\u0438\\u043a\\u0430\\u0446\\u0438\\u044f \\u0434\\u043b\\u044f \\u0432\\u0442\\u043e\\u0440\\u0438\\u0447\\u043d\\u043e\\u0433\\u043e \\u0430\\u043d\\u0430\\u043b\\u0438\\u0437\\u0430: \\u043a\\u043b\\u0430\\u0441\\u0441 (text / math / symbolic / world-knowledge / other), \\u0442\\u0440\\u0443\\u0434\\u043d\\u043e\\u0441\\u0442\\u044c (\\u043f\\u043e \\u043e\\u043f\\u0443\\u0431\\u043b\\u0438\\u043a\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u043c \\u0431\\u0430\\u0437\\u043e\\u0432\\u044b\\u043c \\u0442\\u043e\\u0447\\u043a\\u0430\\u043c), \\u0438 \\u00abCoT-helps vs CoT-hurts\\u00bb \\u043c\\u043d\\u043e\\u0436\\u0435\\u0441\\u0442\\u0432\\u043e (\\u043d\\u0430\\u043f\\u0440. `causal_judgment`, `date_understanding`, `formality_fallacy`, `nonsense_questions`, `penguins_in_a_table`, `pressure`) \\u2014 \\u0447\\u0442\\u043e\\u0431\\u044b \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c, \\u0433\\u0434\\u0435 \\u0438\\u043c\\u0435\\u043d\\u043d\\u043e \\u0432\\u044b\\u0438\\u0433\\u0440\\u044b\\u0432\\u0430\\u0435\\u0442 \\u043e\\u043f\\u0442\\u0438\\u043c\\u0438\\u0437\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u0430\\u044f \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u044f.\\n\\n**\\u041c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0430.** \\u0422\\u043e\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c \\u043f\\u043e grading-\\u043f\\u0440\\u0430\\u0432\\u0438\\u043b\\u0430\\u043c big-bench: `exact_str_match`/\\u043a\\u0430\\u0441\\u0442\\u043e\\u043c\\u043d\\u044b\\u0435 \\u0433\\u0440aders \\u0434\\u043b\\u044f \\u0431\\u043e\\u043b\\u044c\\u0448\\u0438\\u043d\\u0441\\u0442\\u0432\\u0430 \\u0437\\u0430\\u0434\\u0430\\u0447. \\u041f\\u0435\\u0440\\u0432\\u0438\\u0447\\u043d\\u043e: accuracy \\u043d\\u0430 task \\u2192 \\u043c\\u0430\\u043a\\u0440\\u043e-\\u0441\\u0440\\u0435\\u0434\\u043d\\u0435\\u0435 \\u043f\\u043e held-out tasks. \\u041e\\u0431\\u044f\\u0437\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e \\u0434\\u0432\\u043e\\u0439\\u043d\\u043e\\u0439 \\u043e\\u0442\\u0447\\u0451\\u0442 \\u043f\\u0430\\u0440\\u0441\\u0438\\u043d\\u0433\\u0430: strict extraction \\u0438 \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0439 fallback-\\u044d\\u043a\\u0441\\u0442\\u0440\\u0430\\u043a\\u0442\\u043e\\u0440, \\u0447\\u0442\\u043e\\u0431\\u044b \\u043f\\u0440\\u043e\\u0432\\u0430\\u043b\\u044b \\u0438\\u0437\\u0432\\u043b\\u0435\\u0447\\u0435\\u043d\\u0438\\u044f \\u043e\\u0442\\u0432\\u0435\\u0442\\u0430 \\u043d\\u0435 \\u0438\\u043c\\u0438\\u0442\\u0438\\u0440\\u043e\\u0432\\u0430\\u043b\\u0438 \\u00ab\\u0443\\u043c\\u043d\\u0443\\u044e \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u044e\\u00bb. \\u0414\\u043b\\u044f 2\\u20133 \\u0437\\u0430\\u0434\\u0430\\u0447, \\u0433\\u0434\\u0435 big-bench \\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 LLM-judge, \\u2014 \\u0434\\u0435\\u0442\\u0435\\u0440\\u043c\\u0438\\u043d\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u0430\\u044f \\u0437\\u0430\\u043c\\u0435\\u043d\\u0430 \\u0438\\u043b\\u0438 \\u0438\\u0441\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u0438\\u0435 \\u0438\\u0437 primary-\\u043d\\u0430\\u0431\\u043e\\u0440\\u0430 (\\u0440\\u0438\\u0441\\u043a-\\u0444\\u043b\\u0430\\u0433).\\n\\n**\\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c \\u043f\\u0435\\u0440\\u0435\\u043e\\u0431\\u0443\\u0447\\u0435\\u043d\\u0438\\u044f/\\u043a\\u043e\\u043d\\u0444\\u0430\\u0443\\u043d\\u0434\\u043e\\u0432:** (i) primary \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043d\\u0430 test-tasks; (ii) \\u044f\\u0432\\u043d\\u044b\\u0439 train\\u2013test gap; (iii) \\u0430\\u0443\\u0434\\u0438\\u0442 \\u0443\\u0442\\u0435\\u0447\\u043a\\u0438 \\u2014 n-gram-\\u043f\\u0435\\u0440\\u0435\\u0441\\u0435\\u0447\\u0435\\u043d\\u0438\\u0435 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0430 OPRO-\\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0438 \\u0441 item'\\u0430\\u043c\\u0438 test-\\u0437\\u0430\\u0434\\u0430\\u0447 (\\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u044f \\u043d\\u0435 \\u0434\\u043e\\u043b\\u0436\\u043d\\u0430 \\u0441\\u043e\\u0434\\u0435\\u0440\\u0436\\u0430\\u0442\\u044c \\u0444\\u043e\\u0440\\u043c\\u0443\\u043b\\u0438\\u0440\\u043e\\u0432\\u043a\\u0438/\\u043e\\u0442\\u0432\\u0435\\u0442\\u044b test-\\u043f\\u0440\\u0438\\u043c\\u0435\\u0440\\u043e\\u0432); (iv) \\u0434\\u043b\\u0438\\u043d\\u0430 \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0438 \\u043a\\u0430\\u043a \\u043a\\u043e\\u0432\\u0430\\u0440\\u0438\\u0430\\u0442\\u0430 \\u0438 \\u0430\\u0431\\u043b\\u044f\\u0446\\u0438\\u044f A\\u2032; (v) \\u0442\\u0440\\u0435\\u0431\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435 \\u0441\\u043e\\u0433\\u043b\\u0430\\u0441\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u0441\\u0442\\u0438 \\u0437\\u043d\\u0430\\u043a\\u0430: \\u043f\\u0440\\u0435\\u0432\\u043e\\u0441\\u0445\\u043e\\u0434\\u0441\\u0442\\u0432\\u043e \\u043d\\u0430 \\u0431\\u043e\\u043b\\u044c\\u0448\\u0438\\u043d\\u0441\\u0442\\u0432\\u0435 test-\\u0437\\u0430\\u0434\\u0430\\u0447 (sign test), \\u0430 \\u043d\\u0435 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0432 \\u0441\\u0440\\u0435\\u0434\\u043d\\u0435\\u043c; (vi) \\u0435\\u0441\\u043b\\u0438 \\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u043d\\u044b \\u0447\\u0435\\u043a\\u043f\\u043e\\u0438\\u043d\\u0442\\u044b \\u2014 \\u0447\\u0443\\u0432\\u0441\\u0442\\u0432\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u044c \\u043a \\u0438\\u0442\\u0435\\u0440\\u0430\\u0446\\u0438\\u0438 \\u043e\\u043f\\u0442\\u0438\\u043c\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438.\\n\\n**\\u041c\\u043e\\u0434\\u0435\\u043b\\u044c \\u0438 \\u0434\\u0435\\u043a\\u043e\\u0434\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435.** \\u0412 OPRO \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u043b\\u0441\\u044f PaLM 2-L (\\u043d\\u0435\\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u0435\\u043d). \\u041f\\u0440\\u0435\\u0434\\u043b\\u0430\\u0433\\u0430\\u044e: primary \\u2014 \\u043e\\u0434\\u043d\\u0430 \\u043e\\u0442\\u043a\\u0440\\u044b\\u0442\\u0430\\u044f instruction-\\u043c\\u043e\\u0434\\u0435\\u043b\\u044c ~7\\u20138B (\\u043e\\u0434\\u043d\\u0430 familia, \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0439 \\u0447\\u0435\\u043a\\u043f\\u043e\\u0439\\u043d\\u0442, \\u0447\\u0430\\u0442-\\u0448\\u0430\\u0431\\u043b\\u043e\\u043d \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d); \\u043e\\u043f\\u0446\\u0438\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e \\u2014 \\u043e\\u0434\\u043d\\u0430 \\u0441\\u0438\\u043b\\u044c\\u043d\\u0430\\u044f API-\\u043c\\u043e\\u0434\\u0435\\u043b\\u044c \\u043f\\u0440\\u0438 \\u043d\\u0430\\u043b\\u0438\\u0447\\u0438\\u0438 \\u043a\\u043b\\u044e\\u0447\\u0430, \\u0438 PaLM-2-L \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043a\\u0430\\u043a \\u043b\\u0438\\u0442\\u0435\\u0440\\u0430\\u0442\\u0443\\u0440\\u043d\\u044b\\u0439 reference. \\u0414\\u0435\\u043a\\u043e\\u0434\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435: T=0 \\u0434\\u043b\\u044f primary (\\u0432\\u043e\\u0441\\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u0434\\u0438\\u043c\\u043e\\u0441\\u0442\\u044c) + replicate \\u043f\\u0440\\u0438 T=0.7 \\u0434\\u043b\\u044f \\u043e\\u0446\\u0435\\u043d\\u043a\\u0438 \\u0434\\u0438\\u0441\\u043f\\u0435\\u0440\\u0441\\u0438\\u0438; \\u043e\\u0434\\u0438\\u043d \\u0438 \\u0442\\u043e\\u0442 \\u0436\\u0435 seed \\u043d\\u0430 \\u0432\\u0441\\u0435 \\u0443\\u0441\\u043b\\u043e\\u0432\\u0438\\u044f.\\n\\n**Run/seed \\u0438 \\u0431\\u044e\\u0434\\u0436\\u0435\\u0442.** 3 \\u0441\\u0438\\u0434 \\u00d7 3 \\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u044b\\u0445 \\u0443\\u0441\\u043b\\u043e\\u0432\\u0438\\u044f. \\u041f\\u043e\\u043b\\u043d\\u044b\\u0439 BBH (27\\u00d71000 items) = ~243k \\u0433\\u0435\\u043d\\u0435\\u0440\\u0430\\u0446\\u0438\\u0439 \\u2014 \\u043d\\u0435\\u0440\\u0435\\u0430\\u043b\\u0438\\u0441\\u0442\\u0438\\u0447\\u043d\\u043e; \\u043f\\u0440\\u0435\\u0434\\u043b\\u0430\\u0433\\u0430\\u044e \\u0441\\u0442\\u0440\\u0430\\u0442\\u0438\\u0444\\u0438\\u0446\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0439 \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0439 \\u043f\\u043e\\u0434\\u0432\\u0437\\u044f\\u0442 200 items/\\u0437\\u0430\\u0434\\u0430\\u0447\\u0443 (\\u0438\\u043d\\u0434\\u0435\\u043a\\u0441\\u044b \\u043e\\u0431\\u0449\\u0438\\u0435 \\u0434\\u043b\\u044f \\u0443\\u0441\\u043b\\u043e\\u0432\\u0438\\u0439 \\u2192 \\u043f\\u0430\\u0440\\u043d\\u043e\\u0441\\u0442\\u044c): \\u224848.6k \\u0433\\u0435\\u043d\\u0435\\u0440\\u0430\\u0446\\u0438\\u0439 \\u043d\\u0430 27 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0430\\u0445, \\u0438\\u043b\\u0438 \\u224825k, \\u0435\\u0441\\u043b\\u0438 \\u043e\\u0433\\u0440\\u0430\\u043d\\u0438\\u0447\\u0438\\u0442\\u044c held-out-\\u0437\\u0430\\u0434\\u0430\\u0447\\u0430\\u043c\\u0438 (~14). \\u0411\\u044e\\u0434\\u0436\\u0435\\u0442 \\u0432\\u044b\\u0431\\u0438\\u0440\\u0430\\u0435\\u0442\\u0441\\u044f \\u043f\\u043e\\u0441\\u043b\\u0435 \\u0432\\u0430\\u0448\\u0435\\u0433\\u043e \\u043e\\u0442\\u0432\\u0435\\u0442\\u0430.\\n\\n**\\u0421\\u0442\\u0430\\u0442\\u0438\\u0441\\u0442\\u0438\\u043a\\u0430 \\u0438 \\u0430\\u043d\\u0430\\u043b\\u0438\\u0437.** \\u041f\\u0435\\u0440\\u0432\\u0438\\u0447\\u043d\\u044b\\u0439 \\u044d\\u043d\\u0434\\u043f\\u043e\\u0438\\u043d\\u0442 (pre-registered): \\u0394macro-accuracy (A \\u2212 B) \\u043d\\u0430 held-out tasks, superiority-\\u0442\\u0435\\u0441\\u0442 \\u043f\\u0440\\u0438 \\u03b1=0.05; \\u0432\\u0442\\u043e\\u0440\\u0438\\u0447\\u043d\\u044b\\u0439 A \\u2212 C. \\u0412\\u044b\\u0432\\u043e\\u0434: cluster-bootstrap \\u043f\\u043e \\u0437\\u0430\\u0434\\u0430\\u0447\\u0430\\u043c (B=10k) \\u2192 95% CI; per-task \\u2014 \\u043f\\u0430\\u0440\\u043d\\u044b\\u0439 bootstrap \\u043f\\u043e item'\\u0430\\u043c / exact McNemar \\u0434\\u043b\\u044f \\u0434\\u0438\\u0445\\u043e\\u0442\\u043e\\u043c\\u0438\\u0438 \\u0432\\u0435\\u0440\\u043d\\u043e-\\u043d\\u0435\\u0432\\u0435\\u0440\\u043d\\u043e; \\u044d\\u0444\\u0444\\u0435\\u043a\\u0442 \\u2014 \\u0394 \\u0432 \\u043f\\u0443\\u043d\\u043a\\u0442\\u0430\\u0445 + Cliff's delta \\u043d\\u0430 task-\\u0443\\u0440\\u043e\\u0432\\u043d\\u0435. \\u041f\\u043e\\u043f\\u0440\\u0430\\u0432\\u043a\\u0430 \\u043d\\u0430 \\u043c\\u043d\\u043e\\u0436\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u043e\\u0441\\u0442\\u044c: Holm-Bonferroni (\\u0438\\u043b\\u0438 BH) \\u043f\\u043e \\u0432\\u0441\\u0435\\u043c 2\\u00d7#task \\u043f\\u0430\\u0440\\u043d\\u044b\\u043c \\u0442\\u0435\\u0441\\u0442\\u0430\\u043c. \\u041c\\u043e\\u0449\\u043d\\u043e\\u0441\\u0442\\u044c \\u043e\\u0446\\u0435\\u043d\\u0438\\u0432\\u0430\\u0442\\u044c \\u0441\\u0438\\u043c\\u0443\\u043b\\u044f\\u0446\\u0438\\u0435\\u0439 \\u043f\\u043e task-\\u0443\\u0440\\u043e\\u0432\\u043d\\u0435\\u0432\\u043e SD (\\u0430\\u043a\\u043a\\u0443\\u0440\\u0430\\u0442\\u043d\\u043e\\u0441\\u0442\\u044c BBH-\\u0437\\u0430\\u0434\\u0430\\u0447 \\u043a\\u0440\\u0430\\u0439\\u043d\\u0435 \\u0433\\u0435\\u0442\\u0435\\u0440\\u043e\\u0433\\u0435\\u043d\\u043d\\u0430: \\u043e\\u0442 ~0.5 \\u0434\\u043e ~1.0) \\u2014 \\u043f\\u0440\\u0438 14\\u201317 held-out \\u0437\\u0430\\u0434\\u0430\\u0447\\u0430\\u0445 MDE \\u043f\\u043e\\u0440\\u044f\\u0434\\u043a\\u0430 4\\u20136 \\u043f\\u0443\\u043d\\u043a\\u0442\\u043e\\u0432; \\u043e\\u0433\\u0440\\u0430\\u043d\\u0438\\u0447\\u0435\\u043d\\u0438\\u0435 \\u043c\\u043e\\u0449\\u043d\\u043e\\u0441\\u0442\\u0438 \\u2014 \\u0447\\u0438\\u0441\\u043b\\u043e \\u0437\\u0430\\u0434\\u0430\\u0447, \\u0430 \\u043d\\u0435 items. \\u0410\\u043d\\u0430\\u043b\\u0438\\u0437: forest plot \\u0394 \\u043f\\u043e \\u0437\\u0430\\u0434\\u0430\\u0447\\u0430\\u043c \\u2192 \\u0441\\u0442\\u0440\\u0430\\u0442\\u0438\\u0444\\u0438\\u0446\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0435 \\u044d\\u0444\\u0444\\u0435\\u043a\\u0442\\u044b \\u2192 A\\u2032-\\u0430\\u0431\\u043b\\u044f\\u0446\\u0438\\u044f \\u2192 \\u0440\\u0435\\u0433\\u0440\\u0435\\u0441\\u0441\\u0438\\u044f \\u0441\\u043e \\u0441\\u043b\\u0443\\u0447\\u0430\\u0439\\u043d\\u044b\\u043c \\u044d\\u0444\\u0444\\u0435\\u043a\\u0442\\u043e\\u043c \\u0437\\u0430\\u0434\\u0430\\u0447\\u0438 \\u0438 \\u043a\\u043e\\u0432\\u0430\\u0440\\u0438\\u0430\\u0442\\u0430\\u043c\\u0438 (\\u0434\\u043b\\u0438\\u043d\\u0430 \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0438, \\u043a\\u043b\\u0430\\u0441\\u0441 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0438).\\n\\n## 3) \\u042f\\u0432\\u043d\\u044b\\u0435 \\u0434\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u044f \\u0438 \\u043d\\u0435\\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0451\\u043d\\u043d\\u043e\\u0441\\u0442\\u0438\\n\\n\\u0414\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u044f (\\u043d\\u0435 \\u0442\\u0440\\u0435\\u0431\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f \\u0437\\u0430\\u0434\\u0430\\u0447\\u0438):\\n1. \\u00ab\\u0421\\u0442\\u0430\\u043d\\u0434\\u0430\\u0440\\u0442\\u043d\\u0430\\u044f \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c\\u00bb \\u0432 \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441\\u0435 \\u043d\\u0435 \\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0435\\u043d\\u0430; \\u0441\\u0447\\u0438\\u0442\\u0430\\u044e \\u043f\\u0435\\u0440\\u0432\\u0438\\u0447\\u043d\\u043e\\u0439 \\u043e\\u0434\\u043d\\u0443 \\u043e\\u0442\\u043a\\u0440\\u044b\\u0442\\u0443\\u044e 7\\u20138B instruct-\\u043c\\u043e\\u0434\\u0435\\u043b\\u044c, \\u0430 PaLM 2-L \\u2014 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e reference (\\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u044b OPRO \\u043d\\u0430 PaLM-2-L \\u043d\\u0435 \\u043f\\u0435\\u0440\\u0435\\u043d\\u043e\\u0441\\u044f\\u0442\\u0441\\u044f \\u0430\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438 \\u043d\\u0430 \\u043c\\u0435\\u043d\\u044c\\u0448\\u0438\\u0435 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0438).\\n2. OPRO-\\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u044f \\u0434\\u043b\\u044f BBH \\u2014 \\u043e\\u0434\\u043d\\u0430 \\u00abgeneral\\u00bb \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u044f, \\u043e\\u043f\\u0442\\u0438\\u043c\\u0438\\u0437\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u0430\\u044f \\u043d\\u0430 \\u043f\\u043e\\u0434\\u043c\\u043d\\u043e\\u0436\\u0435\\u0441\\u0442\\u0432\\u0435 BBH-\\u0437\\u0430\\u0434\\u0430\\u0447 (train) \\u0438 \\u043e\\u0446\\u0435\\u043d\\u0451\\u043d\\u043d\\u0430\\u044f \\u043d\\u0430 held-out; \\u043a\\u043e\\u043d\\u043a\\u0440\\u0435\\u0442\\u043d\\u044b\\u0439 \\u0441\\u043e\\u0441\\u0442\\u0430\\u0432 train/test-\\u0440\\u0430\\u0437\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u044f \\u0438 \\u0441\\u0430\\u043c \\u0442\\u0435\\u043a\\u0441\\u0442 \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0438 \\u0442\\u0440\\u0435\\u0431\\u0443\\u044e\\u0442 \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a\\u0430.\\n3. \\u0411\\u0430\\u0437\\u043e\\u0432\\u044b\\u0439 CoT \\u2014 \\u0440\\u043e\\u0432\\u043d\\u043e zero-shot \\u0441\\u0442\\u0440\\u043e\\u043a\\u0430 `Let's think step by step.`; few-shot CoT \\u2014 \\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 reference, \\u043d\\u0435 \\u00ab\\u0431\\u0430\\u0437\\u0430\\u00bb.\\n4. \\u041e\\u0441\\u043d\\u043e\\u0432\\u043d\\u0430\\u044f \\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0430 \\u2014 \\u0442\\u043e\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c \\u0441 \\u0430\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u043c grading; LLM-judge-\\u0437\\u0430\\u0434\\u0430\\u0447\\u0438 \\u043b\\u0438\\u0431\\u043e \\u0438\\u0441\\u043a\\u043b\\u044e\\u0447\\u0430\\u044e\\u0442\\u0441\\u044f \\u0438\\u0437 primary, \\u043b\\u0438\\u0431\\u043e \\u043f\\u043e\\u043b\\u0443\\u0447\\u0430\\u044e\\u0442 \\u0434\\u0435\\u0442\\u0435\\u0440\\u043c\\u0438\\u043d\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0439 \\u0441\\u0443\\u0440\\u0440\\u043e\\u0433\\u0430\\u0442.\\n5. \\u0418\\u0441\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u0435 \\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 \\u0432\\u043d\\u0435\\u0448\\u043d\\u0435\\u0439 \\u0441\\u0440\\u0435\\u0434\\u044b (GPU/API + \\u0443\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043a\\u0430 torch/transformers/datasets/scipy + \\u0437\\u0430\\u0433\\u0440\\u0443\\u0437\\u043a\\u0430 BBH); \\u0432 \\u0442\\u0435\\u043a\\u0443\\u0449\\u0435\\u043c sandbox \\u044d\\u0442\\u043e \\u043d\\u0435\\u0432\\u043e\\u0437\\u043c\\u043e\\u0436\\u043d\\u043e.\\n\\n\\u041d\\u0435\\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0451\\u043d\\u043d\\u043e\\u0441\\u0442\\u0438, \\u043a\\u043e\\u0442\\u043e\\u0440\\u044b\\u0435 \\u043d\\u0443\\u0436\\u043d\\u043e \\u0437\\u0430\\u043a\\u0440\\u044b\\u0442\\u044c \\u0432\\u0430\\u043c:\\n- **U1**: \\u043e\\u0442\\u043a\\u0443\\u0434\\u0430 \\u0431\\u0435\\u0440\\u0451\\u043c \\u0442\\u0435\\u043a\\u0441\\u0442(\\u044b) OPRO-\\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0439 \\u0438 train/test-\\u0440\\u0430\\u0437\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u0435 BBH (\\u043f\\u0440\\u0438\\u043b\\u043e\\u0436\\u0435\\u043d\\u0438\\u0435 \\u0441\\u0442\\u0430\\u0442\\u044c\\u0438 vs \\u043b\\u043e\\u0433\\u0438 \\u0440\\u0435\\u043f\\u043e\\u0437\\u0438\\u0442\\u043e\\u0440\\u0438\\u044f)? \\u0418\\u0445 \\u043d\\u0435\\u0442 \\u043e\\u0444\\u043b\\u0430\\u0439\\u043d.\\n- **U2**: \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a BBH (Big-Bench-HIT / `lukaemon/bbh` / big-bench original) \\u0438 \\u0432\\u0435\\u0440\\u0441\\u0438\\u044f/1000-item \\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442, \\u0432\\u043a\\u043b\\u044e\\u0447\\u0430\\u044f distractor-\\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442\\u044b.\\n- **U3**: \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c \\u0438 \\u0431\\u044e\\u0434\\u0436\\u0435\\u0442 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u043e\\u0432 (\\u043f\\u043e\\u0434\\u0432\\u0437\\u044f\\u0442 200 items \\u00d7 14 \\u0437\\u0430\\u0434\\u0430\\u0447 \\u00d7 3 \\u0443\\u0441\\u043b\\u043e\\u0432\\u0438\\u044f \\u00d7 3 \\u0441\\u0438\\u0434 \\u2248 25k \\u0437\\u0430\\u043f\\u0440\\u043e\\u0441\\u043e\\u0432 \\u2014 \\u043f\\u0440\\u0438\\u0435\\u043c\\u043b\\u0435\\u043c\\u043e \\u043b\\u0438; \\u0435\\u0441\\u0442\\u044c \\u043b\\u0438 API-\\u043a\\u043b\\u044e\\u0447\\u0438/GPU).\\n- **U4**: \\u043d\\u0443\\u0436\\u043d\\u0430 \\u043b\\u0438 A\\u2032-\\u0430\\u0431\\u043b\\u044f\\u0446\\u0438\\u044f (\\u0441\\u043d\\u044f\\u0442\\u0438\\u0435 few-shot \\u043f\\u0440\\u0438\\u043c\\u0435\\u0440\\u043e\\u0432) \\u0438 \\u0447\\u0435\\u043a\\u043f\\u043e\\u0438\\u043d\\u0442-\\u0430\\u043d\\u0430\\u043b\\u0438\\u0437 \\u0432 \\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u043e\\u043c \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0435 \\u0438\\u043b\\u0438 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043a\\u0430\\u043a \\u043e\\u043f\\u0446\\u0438\\u044f.\\n- **U5**: \\u043a\\u0430\\u043a \\u0442\\u0440\\u0430\\u043a\\u0442\\u0443\\u0435\\u043c grading \\u0437\\u0430\\u0434\\u0430\\u0447, \\u0442\\u0440\\u0435\\u0431\\u0443\\u044e\\u0449\\u0438\\u0445 LLM-judge.\\n\\n\\u041d\\u0438\\u0447\\u0435\\u0433\\u043e \\u043d\\u0435 \\u0437\\u0430\\u043f\\u0443\\u0441\\u043a\\u0430\\u043b\\u043e\\u0441\\u044c \\u0438 \\u043d\\u0435 \\u043c\\u043e\\u0436\\u0435\\u0442 \\u0431\\u044b\\u0442\\u044c \\u0437\\u0430\\u043f\\u0443\\u0449\\u0435\\u043d\\u043e \\u0432 \\u044d\\u0442\\u043e\\u043c \\u043e\\u043a\\u0440\\u0443\\u0436\\u0435\\u043d\\u0438\\u0438; \\u0443\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0435\\u043d\\u0438\\u0439 \\u043e \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u0430\\u0445 \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442\\u0430 \\u043d\\u0435\\u0442 \\u0438 \\u043d\\u0435 \\u0431\\u0443\\u0434\\u0435\\u0442.\\n\\n**\\u0417\\u0430\\u043f\\u0440\\u0430\\u0448\\u0438\\u0432\\u0430\\u044e approval \\u043d\\u0430 \\u044d\\u0442\\u043e\\u0442 approach (+ \\u043e\\u0442\\u0432\\u0435\\u0442\\u044b \\u043f\\u043e U1\\u2013U5), \\u043f\\u043e\\u0441\\u043b\\u0435 \\u0447\\u0435\\u0433\\u043e \\u043f\\u043e\\u0434\\u0433\\u043e\\u0442\\u043e\\u0432\\u043b\\u044e \\u043f\\u043e\\u043b\\u043d\\u044b\\u0439 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d (stage=result).**\", \"evidence\": \"\\u0420\\u0435\\u043f\\u043e\\u0437\\u0438\\u0442\\u043e\\u0440\\u0438\\u0439/\\u043e\\u043a\\u0440\\u0443\\u0436\\u0435\\u043d\\u0438\\u0435 (\\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0435\\u043d\\u043e \\u043a\\u043e\\u043c\\u0430\\u043d\\u0434\\u0430\\u043c\\u0438):\\n1. `find /workspace -maxdepth 2` \\u2192 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e `/workspace/task.json`; `du -sh /workspace` = 8.0K. `cat task.json` = \\u043f\\u043e\\u043b\\u0435 question/context, \\u043f\\u043b\\u044e\\u0441 \\u00abDesign-only task; repositories and compute are not required.\\u00bb\\n2. `find / -xdev -iname '*opro*' -o -iname '*big_bench*' -o -iname '*bbh*'` \\u2192 \\u043f\\u0443\\u0441\\u0442\\u043e (\\u043d\\u0435\\u0442 \\u043a\\u043e\\u0434\\u0430 OPRO, \\u043d\\u0435\\u0442 BBH-\\u0434\\u0430\\u043d\\u043d\\u044b\\u0445). `find / -xdev -name '.git'` \\u2192 \\u043f\\u0443\\u0441\\u0442\\u043e; `/home/actor` \\u043f\\u0443\\u0441\\u0442; `/opt /srv /data /mnt` \\u043f\\u0443\\u0441\\u0442\\u044b; `~/.cache` (\\u0432\\u043a\\u043b\\u044e\\u0447\\u0430\\u044f huggingface) \\u043e\\u0442\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0443\\u0435\\u0442.\\n3. `python3 -c import numpy|pandas|datasets|torch|openai|google.generativeai|scipy|sklearn` \\u2192 ModuleNotFoundError \\u0434\\u043b\\u044f \\u0432\\u0441\\u0435\\u0445; stdlib `statistics`/`math` \\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u043d\\u044b. Python 3.14.4; `pip3 list` \\u2014 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u043d\\u044b\\u0435 \\u0434\\u0438\\u0441\\u0442\\u0440\\u0438\\u0431\\u0443\\u0442\\u0438\\u0432\\u043d\\u044b\\u0435 \\u043f\\u0430\\u043a\\u0435\\u0442\\u044b.\\n4. \\u0421\\u0435\\u0442\\u044c \\u0432\\u044b\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u0430: `socket.create_connection(('pypi.org',443),3)` \\u2192 `socket.gaierror: Temporary failure in name resolution`; \\u0432 `env` \\u043d\\u0435\\u0442 API-\\u043a\\u043b\\u044e\\u0447\\u0435\\u0439/\\u0442\\u043e\\u043a\\u0435\\u043d\\u043e\\u0432/\\u043f\\u0440\\u043e\\u043a\\u0441\\u0438; \\u043e\\u0444\\u043b\\u0430\\u0439\\u043d wheels (`*.whl`) \\u043d\\u0435 \\u043d\\u0430\\u0439\\u0434\\u0435\\u043d\\u044b.\\n5. \\u0412\\u044b\\u0447\\u0438\\u0441\\u043b\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u0435 \\u0440\\u0435\\u0441\\u0443\\u0440\\u0441\\u044b: `nproc` = 224, `sched_getaffinity` = 224, GPU \\u043d\\u0435\\u0442 (gpu_enabled=false \\u0432 \\u043a\\u043e\\u043d\\u0444\\u0438\\u0433\\u0443\\u0440\\u0430\\u0446\\u0438\\u0438).\\n\\u041b\\u043e\\u0433\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0435 \\u043e\\u043f\\u043e\\u0440\\u044b \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0430 (\\u0438\\u0437 \\u0432\\u043d\\u0435\\u0448\\u043d\\u0438\\u0445 \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a\\u043e\\u0432, \\u043d\\u0435 \\u0438\\u0437 \\u0440\\u0435\\u043f\\u043e\\u0437\\u0438\\u0442\\u043e\\u0440\\u0438\\u044f): BBH = 27 \\u043f\\u043e\\u0434\\u0437\\u0430\\u0434\\u0430\\u0447 (Suzgun et al. 2022); \\u0431\\u0430\\u0437\\u043e\\u0432\\u044b\\u0439 zero-shot CoT \\u00abLet's think step by step.\\u00bb (Kojima et al. 2022); OPRO \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u043b PaLM 2-L \\u0434\\u043b\\u044f \\u043e\\u043f\\u0442\\u0438\\u043c\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438/\\u043e\\u0446\\u0435\\u043d\\u043a\\u0438 \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0439 \\u2014 \\u0432\\u0441\\u0451 \\u044d\\u0442\\u043e \\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 \\u0432\\u043d\\u0435\\u0448\\u043d\\u0435\\u0439 \\u0437\\u0430\\u0433\\u0440\\u0443\\u0437\\u043a\\u0438, \\u0442.\\u043a. \\u043e\\u0444\\u043b\\u0430\\u0439\\u043d \\u043d\\u0438\\u0447\\u0435\\u0433\\u043e \\u043d\\u0435\\u0442.\", \"assumptions\": [\"\\u0421\\u043e\\u0441\\u0442\\u0430\\u0432 train/test-\\u0440\\u0430\\u0437\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u044f BBH \\u0438 \\u0442\\u0435\\u043a\\u0441\\u0442 OPRO-\\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0438 \\u0431\\u0443\\u0434\\u0443\\u0442 \\u0432\\u0437\\u044f\\u0442\\u044b \\u0438\\u0437 \\u0432\\u043d\\u0435\\u0448\\u043d\\u0438\\u0445 \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a\\u043e\\u0432 (\\u0441\\u0442\\u0430\\u0442\\u044c\\u044f/\\u0440\\u0435\\u043f\\u043e\\u0437\\u0438\\u0442\\u043e\\u0440\\u0438\\u0439 OPRO), \\u043a\\u043e\\u0442\\u043e\\u0440\\u044b\\u0445 \\u0441\\u0435\\u0439\\u0447\\u0430\\u0441 \\u043d\\u0435\\u0442 \\u0432 sandbox\", \"\\u041f\\u0435\\u0440\\u0432\\u0438\\u0447\\u043d\\u0430\\u044f \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c \\u2014 \\u043e\\u0434\\u043d\\u0430 \\u043e\\u0442\\u043a\\u0440\\u044b\\u0442\\u0430\\u044f instruct-\\u043c\\u043e\\u0434\\u0435\\u043b\\u044c ~7-8B; PaLM 2-L \\u0438\\u0437 \\u043e\\u0440\\u0438\\u0433\\u0438\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0439 OPRO-\\u0441\\u0442\\u0430\\u0442\\u044c\\u0438 \\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u0435\\u043d \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043a\\u0430\\u043a \\u043b\\u0438\\u0442\\u0435\\u0440\\u0430\\u0442\\u0443\\u0440\\u043d\\u044b\\u0439 reference\", \"\\u0411\\u0430\\u0437\\u043e\\u0432\\u044b\\u0439 CoT = \\u0440\\u043e\\u0432\\u043d\\u043e \\u0441\\u0442\\u0440\\u043e\\u043a\\u0430 'Let's think step by step.' (zero-shot), few-shot CoT \\u2014 \\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 optional reference\", \"\\u041f\\u0435\\u0440\\u0432\\u0438\\u0447\\u043d\\u0430\\u044f \\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0430 \\u2014 \\u0430\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0430\\u044f \\u0442\\u043e\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c (exact/custom graders big-bench); LLM-judge-\\u0437\\u0430\\u0434\\u0430\\u0447\\u0438 \\u0438\\u0441\\u043a\\u043b\\u044e\\u0447\\u0430\\u044e\\u0442\\u0441\\u044f \\u0438\\u0437 primary \\u0438\\u043b\\u0438 \\u043f\\u043e\\u043b\\u0443\\u0447\\u0430\\u044e\\u0442 \\u0434\\u0435\\u0442\\u0435\\u0440\\u043c\\u0438\\u043d\\u0438\\u044